// === TECHNICAL INDICATORS ===
rsi_period = input.int(14, "RSI Period", minval=1, group="Technical Indicators")
rsi_overbought = input.int(70, "RSI Overbought Level", minval=50, maxval=100, group="Technical Indicators")
