// server/video-processor.ts
import { spawn } from "child_process";
import fs2 from "fs";
import path2 from "path";
import { v4 as uuidv4 } from "uuid";
var uploadsDir = path2.join(process.cwd(), "uploads");
var framesDir = path2.join(uploadsDir, "frames");
if (!fs2.existsSync(framesDir)) {
  fs2.mkdirSync(framesDir, { recursive: true });
}
async function extractFramesFromVideo(videoBuffer, numFrames = 4, videoMimeType = "video/mp4") {
  const videoId = uuidv4();
  const extension = videoMimeType.includes("quicktime") ? "mov" : videoMimeType.includes("webm") ? "webm" : "mp4";
  const videoPath = path2.join(uploadsDir, `${videoId}.${extension}`);
  const framePattern = path2.join(framesDir, `${videoId}_frame_%03d.jpg`);
  try {
    await fs2.promises.writeFile(videoPath, videoBuffer);
    console.log("Video saved to:", videoPath);
    const duration = await getVideoDuration(videoPath);
    console.log("Video duration:", duration, "seconds");
    if (duration <= 0) {
      throw new Error("Could not determine video duration");
    }
    const interval = duration / (numFrames + 1);
    const frames = [];
    for (let i = 1; i <= numFrames; i++) {
      const timestamp2 = interval * i;
      const framePath = path2.join(framesDir, `${videoId}_frame_${String(i).padStart(3, "0")}.jpg`);
      await extractFrameAtTime(videoPath, framePath, timestamp2);
      if (fs2.existsSync(framePath)) {
        const frameBuffer = await fs2.promises.readFile(framePath);
        const base64 = frameBuffer.toString("base64");
        frames.push({
          path: framePath,
          timestamp: timestamp2,
          base64
        });
      }
    }
    await fs2.promises.unlink(videoPath).catch(() => {
    });
    console.log(`Extracted ${frames.length} frames from video`);
    return frames;
  } catch (error) {
    await fs2.promises.unlink(videoPath).catch(() => {
    });
    console.error("Error extracting frames:", error);
    throw error;
  }
}
async function getVideoDuration(videoPath) {
  return new Promise((resolve, reject) => {
    const ffprobe = spawn("ffprobe", [
      "-v",
      "error",
      "-show_entries",
      "format=duration",
      "-of",
      "default=noprint_wrappers=1:nokey=1",
      videoPath
    ]);
    let output = "";
    let errorOutput = "";
    ffprobe.stdout.on("data", (data) => {
      output += data.toString();
    });
    ffprobe.stderr.on("data", (data) => {
      errorOutput += data.toString();
    });
    ffprobe.on("close", (code) => {
      if (code === 0) {
        const duration = parseFloat(output.trim());
        resolve(isNaN(duration) ? 0 : duration);
      } else {
        console.error("ffprobe error:", errorOutput);
        reject(new Error(`ffprobe exited with code ${code}`));
      }
    });
    ffprobe.on("error", (err) => {
      reject(err);
    });
  });
}
async function extractFrameAtTime(videoPath, outputPath, timestamp2) {
  return new Promise((resolve, reject) => {
    const ffmpeg = spawn("ffmpeg", [
      "-ss",
      timestamp2.toString(),
      "-i",
      videoPath,
      "-vframes",
      "1",
      "-q:v",
      "2",
      "-y",
      outputPath
    ]);
    let errorOutput = "";
    ffmpeg.stderr.on("data", (data) => {
      errorOutput += data.toString();
    });
    ffmpeg.on("close", (code) => {
      if (code === 0) {
        resolve();
      } else {
        console.error("ffmpeg error:", errorOutput);
        reject(new Error(`ffmpeg exited with code ${code}`));
      }
    });
    ffmpeg.on("error", (err) => {
      reject(err);
    });
  });
}
async function cleanupFrames(frames) {
  for (const frame of frames) {
    try {
      if (fs2.existsSync(frame.path)) {
        await fs2.promises.unlink(frame.path);
      }
    } catch (error) {
      console.error("Error cleaning up frame:", frame.path, error);
    }
  }
}

