function evaluateFuturesDrawdown(preset, accountSize, currentBalance, peakEquity, startingBalance, todayPnL) {
  const trailingMaxDD = preset.trailingMaxDrawdown(accountSize);
  const dailyLossLimit = preset.dailyLossLimit(accountSize);
  const profitTarget = preset.profitTarget(accountSize);
  const drawdownFloor = peakEquity - trailingMaxDD;
  const distanceToFloor = currentBalance - drawdownFloor;
  const distanceToFloorPct = distanceToFloor / trailingMaxDD * 100;
  const dailyLoss = Math.min(0, todayPnL);
  const dailyLossAbs = Math.abs(dailyLoss);
  const dailyLossRemaining = Math.max(0, dailyLossLimit - dailyLossAbs);
  const dailyLossUsedPct = dailyLossAbs / dailyLossLimit * 100;
  const profitGained = currentBalance - startingBalance;
  const progressToTarget = Math.max(0, Math.min(100, profitGained / profitTarget * 100));
  const blockedByTrailingDD = currentBalance <= drawdownFloor;
  const blockedByDailyLimit = dailyLossAbs >= dailyLossLimit;
  let verdict = "SAFE";
  let verdictReason = null;
  if (blockedByTrailingDD) {
    verdict = "BREACHED";
    verdictReason = `Trailing max drawdown breached \u2014 account floor was $${drawdownFloor.toFixed(0)}`;
  } else if (blockedByDailyLimit) {
    verdict = "DANGER";
    verdictReason = `Daily loss limit of $${dailyLossLimit.toFixed(0)} reached \u2014 no more trades today`;
  } else if (distanceToFloor < 200 || dailyLossRemaining < 150) {
    verdict = "DANGER";
    verdictReason = distanceToFloor < 200 ? `Only $${distanceToFloor.toFixed(0)} above trailing drawdown floor` : `Only $${dailyLossRemaining.toFixed(0)} daily loss budget remaining`;
  } else if (distanceToFloorPct < 30 || dailyLossUsedPct > 70) {
    verdict = "WARNING";
    verdictReason = distanceToFloorPct < 30 ? `Approaching trailing DD floor (${distanceToFloorPct.toFixed(0)}% buffer left)` : `${dailyLossUsedPct.toFixed(0)}% of daily loss limit consumed`;
  }
  return {
    currentBalance,
    peakEquity,
    startingBalance,
    drawdownFloor,
    distanceToFloor,
    distanceToFloorPct,
    dailyLoss,
    dailyLossRemaining,
    dailyLossUsedPct,
    profitGained,
    progressToTarget,
    trailingMaxDD,
    dailyLossLimit,
    profitTarget,
    verdict,
    verdictReason,
    blockedByDailyLimit,
    blockedByTrailingDD
  };
}
